function selectCampaigns(campaigns, maxSpend) {
  const n = campaigns.length;
  // Clone to avoid mutation
  const items = campaigns.map(c => ({
    id: c.id,
    dailySpend: c.dailySpend,
    expectedSignups: c.expectedSignups
  }));

  let best = {
    signups: -Infinity,
    spend: Infinity,
    ids: []
  };

  const compareAndUpdate = (candidate) => {
    if (candidate.signups > best.signups ||
        (candidate.signups === best.signups && candidate.spend < best.spend) ||
        (candidate.signups === best.signups && candidate.spend === best.spend &&
         candidate.ids.join(',') < best.ids.join(','))) {
      best = candidate;
    }
  };

  const dfs = (index, curSpend, curSignups, curIds) => {
    if (curSpend > maxSpend) return;
    if (index === n) {
      const sortedIds = [...curIds].sort();
      compareAndUpdate({
        signups: curSignups,
        spend: curSpend,
        ids: sortedIds
      });
      return;
    }

    // Exclude current
    dfs(index + 1, curSpend, curSignups, curIds);

    // Include current
    const item = items[index];
    dfs(
      index + 1,
      curSpend + item.dailySpend,
      curSignups + item.expectedSignups,
      curIds.concat(item.id)
    );
  };

  dfs(0, 0, 0, []);
  return best.ids;
}
